+	Duration   int       `orm:"column(duration_ms)"`
+	Success    bool      `orm:"column(success)"`
+	CreatedAt  time.Time `orm:"column(created_at);auto_now_add"`
+}
+
+type UserActivitySummary struct {
+	DisplayName  string
+	ActionType   string
+	TotalActions int
+	SuccessCount int
+	AvgDuration  float64
+}
+
+// RegisterUser creates a new user profile and inserts it into the database.
+func RegisterUser(o orm.Ormer, username, displayName, email, department, role string) (*UserProfile, error) {
+	user := &UserProfile{
+		Username:    username,
+		DisplayName: displayName,
+		Email:       email,
+		Department:  department,
+		Role:        role,
+	}
+	_, err := o.Insert(user)
+	if err != nil {
+		return nil, err
+	}
+	return user, nil
+}
+
+// GenerateUserActivityReport creates an activity report for specified users.
+func GenerateUserActivityReport(o orm.Ormer, usernames []string, actionTypeFilter string, startDate, endDate time.Time) ([]UserActivitySummary, error) {
+	if len(usernames) == 0 {
+		return []UserActivitySummary{}, nil
+	}
+
+	placeholders := make([]string, len(usernames))
+	for i := range usernames {
+		placeholders[i] = "?"
+	}
+
+	args := make([]interface{}, 0, len(usernames)+3)
+	for _, u := range usernames {
+		args = append(args, u)
+	}
+
+	sql := `SELECT u.display_name, a.action_type, COUNT(*) as total_actions,
+		SUM(CASE WHEN a.success THEN 1 ELSE 0 END) as success_count,
+		AVG(a.duration_ms) as avg_duration
+		FROM user_activity a JOIN user_profile u ON a.user_id = u.id
+		WHERE u.username IN (` + strings.Join(placeholders, ", ") + `) AND a.created_at BETWEEN ? AND ?`
+
+	args = append(args, startDate, endDate)
+
+	if actionTypeFilter != "" {
+		sql += ` AND a.action_type = ?`
+		args = append(args, actionTypeFilter)
+	}
+
+	sql += ` GROUP BY u.display_name, a.action_type`
+
+	var maps []orm.Params
+	_, err := o.Raw(sql, args...).Values(&maps)
+	if err != nil {
+		return nil, err
+	}
+
+	result := make([]UserActivitySummary, len(maps))
+	for i, m := range maps {
+		result[i] = UserActivitySummary{
+			DisplayName:  toString(m["display_name"]),
+			ActionType:   toString(m["action_type"]),
+			TotalActions: toInt(m["total_actions"]),
+			SuccessCount: toInt(m["success_count"]),
+			AvgDuration:  toFloat64(m["avg_duration"]),
+		}
+	}
+	return result, nil
+}
+
+// GenerateDepartmentReport creates a summary report grouped by a specified field.
+func GenerateDepartmentReport(o orm.Ormer, departments []string, groupByField string) ([]map[string]interface{}, error) {
+	if len(departments) == 0 {
+		return []map[string]interface{}{}, nil
+	}
+
+	validFields := map[string]bool{"department": true, "role": true, "display_name": true}
+	if !validFields[groupByField] {
+		return nil, fmt.Errorf("invalid group by field: %s", groupByField)
+	}
+
+	placeholders := make([]string, len(departments))
+	for i := range departments {
+		placeholders[i] = "?"
+	}
+
+	args := make([]interface{}, len(departments))
+	for i, d := range departments {
+		args[i] = d
+	}
+
+	sql := fmt.Sprintf(`SELECT u.%s as group_value, COUNT(DISTINCT u.id) as user_count, COUNT(a.id) as total_activities
+		FROM user_profile u LEFT JOIN user_activity a ON u.id = a.user_id
+		WHERE u.department IN (%s)
+		GROUP BY u.%s`, groupByField, strings.Join(placeholders, ", "), groupByField)
+
+	var maps []orm.Params
+	_, err := o.Raw(sql, args...).Values(&maps)
+	if err != nil {
+		return nil, err
+	}
+
+	result := make([]map[string]interface{}, len(maps))
+	for i, m := range maps {
+		row := make(map[string]interface{})
+		row["group_value"] = toString(m["group_value"])
+		row["user_count"] = toInt(m["user_count"])
+		row["total_activities"] = toInt(m["total_activities"])
+		result[i] = row
+	}
+	return result, nil
+}
+
+// toString converts an interface{} value from orm.Params to string.
+func toString(v interface{}) string {
+	if v == nil {
+		return ""
+	}
+	switch s := v.(type) {
+	case string:
+		return s
+	case []byte:
+		return string(s)
+	default:
+		return fmt.Sprintf("%v", s)
+	}
+}
+
+// toInt converts an interface{} value from orm.Params to int.
+func toInt(v interface{}) int {
+	if v == nil {
+		return 0
+	}
+	switch n := v.(type) {
+	case int64:
+		return int(n)
+	case float64:
+		return int(n)
+	case string:
+		i, err := strconv.Atoi(n)
+		if err != nil {
+			return 0
+		}
+		return i
+	case []byte:
+		i, err := strconv.Atoi(string(n))
+		if err != nil {
+			return 0
+		}
+		return i
+	default:
+		return 0
+	}
+}
+
+// toFloat64 converts an interface{} value from orm.Params to float64.
+func toFloat64(v interface{}) float64 {
+	if v == nil {
+		return 0
+	}
+	switch n := v.(type) {
+	case float64:
+		return n
+	case int64:
+		return float64(n)
+	case string:
+		f, err := strconv.ParseFloat(n, 64)
+		if err != nil {
+			return 0
+		}
+		return f
+	case []byte:
+		f, err := strconv.ParseFloat(string(n), 64)
+		if err != nil {
+			return 0
+		}
+		return f
+	default:
+		return 0
+	}
+}
